function normalizeMediaFile(value){return String(value||'').replace(/^assets\/videos\//,'').replaceAll('\\','/')}
function mediaAssetPath(n){return'assets/videos/'+normalizeMediaFile(n).split('/').map(encodeURIComponent).join('/')}
function mediaBaseName(n){let parts=normalizeMediaFile(n).split('/');return parts[parts.length-1]||n}
function mediaCategory(n){n=normalizeMediaFile(n).toLowerCase();if(n.includes('goal_')||n.includes('heart me'))return'Mål';if(n.includes('leaderboard')||n.includes('top streake'))return'Topplistor';if(n.includes('campaign'))return'Campaigns';if(n.includes('counter')||n.includes('gallery'))return'Gift widgets';if(n.includes('level')||n.includes('ascend'))return'Nivåer';return'Effekter'}
function mediaTitle(n){return(mediaLabels[normalizeMediaFile(n)]||mediaBaseName(n).replace('.mp4','').replaceAll('_',' ').replaceAll('-',' ')).replace(/\s+/g,' ').trim()}
{let old=mediaFiles.indexOf('anime Gift Counter.mp4');if(old>=0)mediaFiles.splice(old,1);mediaFiles.unshift('anime_Gift_Counter.mp4')}
