function showMediaLibrary(){document.querySelectorAll('aside button').forEach(b=>b.classList.toggle('active',b.dataset.extra==='media'));document.querySelector('#title').textContent='Mediabibliotek';let v=document.querySelector('#view');v.innerHTML=`<div class="section-head"><div><h2>Animationer & videowidgets</h2><p>${mediaFiles.length} tillgängliga videofiler · klicka för att förhandsvisa</p></div><button class="primary" id="uploadMedia">＋ Lägg till video</button></div><div class="media-tools"><input id="mediaSearch" placeholder="Sök animation, tema eller widget..."><div id="mediaFilters">${['Alla','Mål','Topplistor','Campaigns','Gift widgets','Nivåer','Effekter'].map((x,i)=>`<button class="${i?'':'active'}" data-filter="${x}">${x}</button>`).join('')}</div></div><div class="media-grid" id="mediaGrid"></div>`;renderMedia(mediaFiles);bindMedia()}
function renderMedia(files){document.querySelector('#mediaGrid').innerHTML=files.map(n=>`<article class="media-card" data-category="${mediaCategory(n)}"><div class="video-wrap"><video data-src="${mediaAssetPath(n)}" muted loop preload="none"></video><button class="media-play">▶</button><span>${mediaCategory(n)}</span></div><div class="media-info"><b>${mediaTitle(n)}</b><small>MP4 · Tillgänglig</small><button class="use-media" data-file="${n}">Använd</button></div></article>`).join('')}
function bindMedia(){document.querySelectorAll('.media-card').forEach(c=>{let video=c.querySelector('video'),play=c.querySelector('.media-play');play.onclick=()=>{document.querySelectorAll('.media-card video').forEach(v=>{if(v!==video){v.pause();v.currentTime=0}});if(!video.dataset.loaded){video.src=video.dataset.src;video.dataset.loaded='1';video.load()}video.paused?(video.play(),play.textContent='❚❚'):(video.pause(),play.textContent='▶')};const useMediaBtn=c.querySelector('.use-media');const catalogKey='catalog:video';useMediaBtn.dataset.catalogKey=catalogKey;useMediaBtn.onclick=()=>{let f=useMediaBtn.dataset.file;state.widgets.push(VyraWidgets.create(catalogKey,{values:{title:mediaTitle(f),value:normalizeMediaFile(f),src:mediaAssetPath(f)}}));save();toast('Videon har lagts på overlay-canvasen')}});document.querySelector('#mediaSearch').oninput=e=>filterMedia(e.target.value,document.querySelector('#mediaFilters .active').dataset.filter);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');filterMedia(document.querySelector('#mediaSearch').value,b.dataset.filter)});document.querySelector('#uploadMedia').onclick=()=>toast('Placera nya MP4-filer i assets/videos')}
function filterMedia(q,cat){q=q.toLowerCase();document.querySelectorAll('.media-card').forEach(c=>c.style.display=(c.textContent.toLowerCase().includes(q)&&(cat==='Alla'||c.dataset.category===cat))?'block':'none')}
