function sanitizeMediaWidgets(){
  let changed=false;
  state.widgets=state.widgets.flatMap(w=>{
    if(w.type!=='video')return[w];
    let file=normalizeMediaFile(w.value||w.src);
    if(!mediaFileSet.has(file)){
      changed=true;
      return [];
    }
    let nextSrc=mediaAssetPath(file),nextTitle=w.title||mediaTitle(file),nextGroup=w.group||videoWidgetGroup(file);
    if(w.value!==file||w.src!==nextSrc||w.title!==nextTitle||w.group!==nextGroup){
      changed=true;
      return [{...w,value:file,src:nextSrc,title:nextTitle,group:nextGroup}];
    }
    return [w];
  });
  if(selected&&!state.widgets.some(w=>w.id===selected)){
    selected=null;
    changed=true;
  }
  if(changed){
    save();
    if(typeof render==='function')render();
  }
  localStorage.setItem('vyra-media-manifest-v2','1');
}
