// Global "🎨 Färgschema" (state.brandKit) opt-in, shared by every template widget below that has its
// own per-widget color field(s). When w.inheritBrandKit is on, the brand kit's field wins over the
// widget's own color; otherwise nothing changes — same "off by default" contract as Last-X Alerts
// and Top Like's Brand Kit skin (see [[vyra_competitor_overlay_analysis]]).
function bk(w,ownValue,kitField,fallback){return (w.inheritBrandKit&&state.brandKit&&state.brandKit[kitField])?state.brandKit[kitField]:(ownValue||fallback)}
// Every widget below invents a shipped placeholder when its field is unset — 658/1000, 43/50, a
// campaign already at 80/250, '@StreamQueen' with 44 999 coins. In the editor that is the point:
// there has to be something to design against. In an OBS overlay it is a number the audience was
// never given, and it hides the difference between "nothing has happened yet" and "the feed died".
//
// This has to live in the renderer rather than be patched out of the DOM afterwards.
// live-zero-state.js disconnects on the first real event, and any render() after that — a gift
// landing in slot 1, say — repaints the OTHER slots straight back to their demo values, mid-stream,
// in front of viewers. A fallback that never fires in overlay mode cannot come back.
const VYRA_OVERLAY=new URLSearchParams(location.search).has('overlay');
function ph(value,placeholder){return value??(VYRA_OVERLAY?0:placeholder)}       // counters where a stored 0 is real
function phv(value,placeholder){return value||(VYRA_OVERLAY?0:placeholder)}      // free-text value fields
function phn(value,placeholder){return value||(VYRA_OVERLAY?'':placeholder)}     // names — no invented person
function bkCheckbox(w){return `<div class="switch-row one"><label><input id="bkInherit" type="checkbox" ${w.inheritBrandKit?'checked':''}> Ärv globalt färgschema (🎨 Färgschema)</label></div>`}
