const basicProps=props;props=function(){let w=liveWidget(selected);if(!w)return basicProps();let special=['Top Gifters','Gift Alerts','Gift Counter','Gift Campaigns','Gift Gallery','Gift Level Up','Fan Level Up'].includes(w.group),generic=special?`<div hidden><input id="pt" value="${w.title||''}"><input id="pv" value="${w.value||''}"></div>`:`<label>Rubrik<input id="pt" value="${w.title||''}"></label><label>Värde<input id="pv" value="${w.value||''}"></label>`;return `<h3>${w.type==='video'?(w.group||'Videowidget'):w.type}</h3>${giftCounterProps(w)}${editableGiftProps(w)}${generic}<div class="property-group"><h4>POSITION & STORLEK</h4><div class="property-grid"><label>X<input id="propX" type="number" value="${w.x||0}"></label><label>Y<input id="propY" type="number" value="${w.y||0}"></label><label>Bredd<input id="propWidth" type="number" min="80" max="900" value="${w.width||300}"></label><label>Lager<input id="propLayer" type="number" min="0" max="99" value="${w.layer||1}"></label></div></div><div class="property-group"><h4>UTSEENDE</h4><label class="range-label">Transparens <b id="opacityValue">${w.opacity??100}%</b><input id="propOpacity" type="range" min="0" max="100" value="${w.opacity??100}"></label><label>Animation<select id="propAnimation"><option value="none">Ingen</option><option value="fade">Tona in</option><option value="pop">Pop</option><option value="slide">Glid in</option><option value="pulse">Puls</option></select></label></div><div class="property-actions"><button id="duplicateWidget">Duplicera</button><button id="toggleWidget">${w.hidden?'Visa':'Dölj'}</button></div><button class="delete" id="del">Ta bort</button>`};
