// ---- Panelens live-vag ------------------------------------------------------------------------
// render() i studio.js ar `viewRoot.innerHTML = m[view]()`. Den river BADE canvasen och
// egenskapspanelen, sa ett anrop mitt i en dragning ersatter det reglage anvandaren haller i —
// dragningen slapper vid forsta pixeln. Uppmatt fore fixen: panelens scrollTop 824 -> 0,
// kontrollen kastad fran y=335 till y=1159 i ett 720px hogt fonster, fokus till BODY.
//
// Live-vagen skriver darfor VARDET och ror bara tva noder: px-etiketten bredvid reglaget och den
// enda widgeten pa canvasen. Ingen omrendering av vyn, i enlighet med arkitekturkontraktet.
function vyraLivePatch(w,el,key,value){
  if(!w||!el)return;
  w[key]=value;
  // Etiketten ser ut som "18px", "4" eller "60%". Bara siffran byts, enheten star kvar — da
  // behover live-vagen inte veta vilken enhet varje enskild kontroll anvander.
  const label=el.parentElement&&el.parentElement.querySelector("b");
  if(label)label.textContent=String(value)+String(label.textContent||"").replace(/^[\d.,-]+/,"");
  const node=document.querySelector(`.canvas [data-id="${w.id}"]`);
  if(node&&typeof wh==="function")node.outerHTML=wh(w);
}
// Nar en andring VERKLIGEN ar klar (change, alltsa nar reglaget slapps) behovs en full
// omrendering: vissa val andrar vilka falt panelen ska ha. Den far dock inte kasta bort var
// anvandaren befann sig — panelen ar ~2900px hog och kontrollen hamnar annars langt utanfor bild.
function vyraRenderKeepingPanel(){
  const panel=document.querySelector(".properties");
  const scroll=panel?panel.scrollTop:0;
  const aktivId=document.activeElement&&document.activeElement.id;
  render();
  const nyPanel=document.querySelector(".properties");
  if(nyPanel)nyPanel.scrollTop=scroll;
  if(aktivId){const ater=document.getElementById(aktivId);if(ater&&typeof ater.focus==="function")ater.focus();}
}
