  return `--lf-x1:${x1.toFixed(1)}px;--lf-x2:${x2.toFixed(1)}px;--lf-x3:${x3.toFixed(1)}px;--lf-lift1:${lift1.toFixed(3)};--lf-lift2:${lift2.toFixed(3)};--lf-r1:${rot1}deg;--lf-r2:${rot2}deg;--lf-r3:${rot3}deg;--lf-breathe:${(0.88+Math.abs(a)*.3).toFixed(2)};`;
