const gifterLevelWh=wh;wh=function(w){return w.type==='templateGifterLevel'?gifterLevelHtml(w):gifterLevelWh(w)};
const gifterLevelProps=props;props=function(){let w=liveWidget(selected);if(!w||w.type!=='templateGifterLevel')return gifterLevelProps();return `<h3>GIFTER LEVEL UP</h3><div class="template-badge">TRIGGER-ALERT</div><div hidden><input id="pt" value="${w.title||''}"><input id="pv" value=""></div><div class="property-group"><h4>INNEHÅLL</h4><label>Rubrik<input id="gifterHeadline" value="${w.gifterHeadline||'GIFTER LEVEL UP'}"></label><label>Nivåtext<input id="gifterLabel" value="${w.gifterLabel||'GIFTER LEVEL'}"></label><label>Nivå<input id="gifterLevel" type="number" min="1" max="50" value="${VyraSafe.num(w.gifterLevel,15)}"></label><label>Namn<input id="gifterName" value="${VyraSafe.text(w.gifterName,'ThunderGifter')}"></label><label>Meddelande<input id="gifterMessage" value="${w.gifterMessage||'Level up!'}"></label><label>Profilbild<input id="gifterProfile" value="${VyraSafe.url(w.profileImage,'assets/images/test-profile.svg')}"></label></div><div class="property-group"><h4>DESIGN</h4><label>Tema<select id="gifterTheme">${Object.keys(gifterLevelThemes).map(t=>`<option value="${t}">${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></label><div class="color-grid"><label>Huvudfärg<input id="gifterColor" type="color" value="${w.gifterColor||'#9965ff'}" ${w.inheritBrandKit?'disabled':''}></label><label>Ljus färg<input id="gifterLight" type="color" value="${w.gifterLight||'#e2d6ff'}" ${w.inheritBrandKit?'disabled':''}></label></div>${bkCheckbox(w)}</div><div class="property-group gifter-trigger-editor"><h4>TRIGGER</h4><div class="switch-row one"><label><input id="gifterAutoTrigger" type="checkbox" ${w.autoTrigger===false?'':'checked'}> Automatisk trigger</label></div><label>Minsta nivå<input id="gifterMinLevel" type="number" min="1" max="50" value="${w.minLevel||1}"></label><label class="range-label">Visningstid <b>${w.gifterDuration||6} sek</b><input id="gifterDuration" type="range" min="2" max="15" value="${w.gifterDuration||6}"></label><button id="testGifterLevel" type="button">▶ Testa gifter level up</button></div>${levelVideoEditor(w,'gifter')}<div class="property-group"><h4>POSITION & STORLEK</h4><div class="property-grid"><label>X<input id="propX" type="number" value="${w.x||0}"></label><label>Y<input id="propY" type="number" value="${w.y||0}"></label><label>Bredd<input id="propWidth" type="number" value="${w.width||270}"></label><label>Lager<input id="propLayer" type="number" value="${w.layer||1}"></label></div></div><button class="delete" id="del">Ta bort</button>`};
const gifterLevelBind=bind;bind=function(){gifterLevelBind();if(view!=='editor')return;let w=liveWidget(selected);if(!w||w.type!=='templateGifterLevel')return;let set=(id,key,num=false)=>{let el=document.querySelector(id);if(!el)return;const las=e=>num?+e.target.value:e.target.value;el.oninput=e=>vyraLivePatch(w,el,key,las(e));el.onchange=e=>{w[key]=las(e);save();vyraRenderKeepingPanel()}};set('#gifterHeadline','gifterHeadline');set('#gifterLabel','gifterLabel');set('#gifterLevel','gifterLevel',true);set('#gifterName','gifterName');set('#gifterMessage','gifterMessage');set('#gifterProfile','profileImage');set('#gifterColor','gifterColor');set('#gifterLight','gifterLight');set('#gifterDuration','gifterDuration',true);set('#gifterLayout','gifterLayout');bkBind(w);let layout=document.querySelector('#gifterLayout');if(layout)layout.value=w.gifterLayout||'profile';let theme=document.querySelector('#gifterTheme');if(theme){theme.value=w.gifterTheme||'royal';theme.onchange=e=>{w.gifterTheme=e.target.value;let c=gifterLevelThemes[w.gifterTheme];w.gifterColor=c[0];w.gifterLight=c[1];save();render()}}let minLevel=document.querySelector('#gifterMinLevel'),autoTrigger=document.querySelector('#gifterAutoTrigger');if(minLevel)minLevel.onchange=e=>{w.minLevel=+e.target.value;save()};if(autoTrigger)autoTrigger.onchange=e=>{w.autoTrigger=e.target.checked;save()};bindLevelVideoEditor(w,'gifter');let test=document.querySelector('#testGifterLevel');if(test)test.onclick=()=>triggerGifterLevelUp({name:w.gifterName,level:w.gifterLevel,profileImage:w.profileImage,__test:true})};
const gifterModelProps=props;props=function(){let html=gifterModelProps(),w=liveWidget(selected);if(!w||w.type!=='templateGifterLevel')return html;return html.replace('<div class="property-group"><h4>INNEHÅLL</h4>','<div class="property-group"><h4>INNEHÅLL</h4><label>Modell<select id="gifterLayout"><option value="profile">Modell 1 · Profil i orbit</option><option value="number">Modell 2 · Stort nivånummer</option><option value="stack">Modell 3 · Diamantstapel</option><option value="sidebadge">Modell 4 · Sidobadge</option><option value="reveal">Modell 5 · Diamantreveal</option><option value="orbitlevel">Modell 6 · Orbitnivå</option><option value="risingtier">Modell 7 · Stigande nivåer</option><option value="flip">Modell 8 · Myntvändning</option><option value="duo">Modell 9 · Kompakt duo</option></select></label>')};
/* TRANSFORMATIONSSEKVENSEN: gammal niva -> kort burst -> ny niva. Rent CSS/DOM, ingen 3D.
   Tiderna ar namngivna sa testet kan bevisa att hela sekvensen ryms i den KORTASTE visningstiden
   (reglaget borjar pa 2 s) - annars hade den nya nivan hunnit forsvinna innan den syntes. */
const XFORM_GAMMAL=450,XFORM_BURST=300,XFORM_TOTAL=1250;
function gifterSattNiva(box,niva,text){const stor=box.querySelector('.gifter-big-level');if(stor)stor.textContent=niva;
  const brick=box.querySelector('.gifter-level-badge strong');if(brick)brick.textContent='LV. '+text}
function gifterTransform(box,fran,till){clearTimeout(box._xf1);clearTimeout(box._xf2);clearTimeout(box._xf3);
  box.classList.remove('gifter-xform-old','gifter-xform-burst','gifter-xform-new');
  /* Fas 1: den gamla nivan star kvar en stund sa tittaren hinner se VAD den byts fran. */
  gifterSattNiva(box,fran,String(fran));box.classList.add('gifter-xform-old');
  box._xf1=setTimeout(()=>{box.classList.remove('gifter-xform-old');box.classList.add('gifter-xform-burst')},XFORM_GAMMAL);
  /* Fas 3: siffran byts mitt i bursten, nar den ar som ljusast - bytet syns aldrig som ett hopp. */
  box._xf2=setTimeout(()=>{gifterSattNiva(box,till,`${fran} → ${till}`);
    box.classList.remove('gifter-xform-burst');box.classList.add('gifter-xform-new')},XFORM_GAMMAL+XFORM_BURST);
  box._xf3=setTimeout(()=>box.classList.remove('gifter-xform-new'),XFORM_TOTAL)}
/* Riktad DOM-patchning i stallet for save()+render(): live-data far inte bli persistent mellan
   sandningar, och hela canvasen ska inte byggas om per alert. */
function gifterPatcha(box,d,w){box.querySelectorAll('.gifter-orbit img,.gifter-bottom-profile img').forEach(img=>{if(d.profileImage)img.src=VyraSafe.src(d.profileImage)});
  const namn=box.querySelector('h3');if(namn&&d.name)namn.textContent=d.name;
  const etikett=box.querySelector('.gifter-level-badge span');if(etikett)etikett.textContent=VyraSafe.text(w.gifterLabel,'GIFTER LEVEL')}
function triggerGifterLevelUp(event={}){let widgets=state.widgets.filter(w=>w.type==='templateGifterLevel');if(!widgets.length)return;const niva=Math.max(1,Math.min(50,Math.round(Number(event.level))||0));const fran=Math.max(1,Math.min(50,Math.round(Number(event.fromLevel))||0));widgets.forEach(w=>{if(!event.__test){if(w.autoTrigger===false)return;if(niva&&niva<(w.minLevel||1))return}let box=document.querySelector(`[data-id="${w.id}"]`);if(!box)return;gifterPatcha(box,event,w);const till=niva||VyraSafe.num(w.gifterLevel,15);gifterTransform(box,fran&&fran<till?fran:Math.max(1,till-1),till);box.classList.remove('gifter-active','gifter-exit','playing-level-video');void box.offsetWidth;playLevelVideo(w,box,till);box.classList.add('gifter-active');clearTimeout(box._gifterTimer);clearTimeout(box._gifterExitTimer);box.style.setProperty('--gifter-exit-duration',Math.max(0,(w.gifterExitDuration||.5)*1000)+'ms');box._gifterTimer=setTimeout(()=>{const exitMs=Math.max(0,(w.gifterExitDuration||.5)*1000);box.classList.add('gifter-exit');box._gifterExitTimer=setTimeout(()=>box.classList.remove('gifter-active','gifter-exit','playing-level-video'),exitMs)},Math.max(0,(w.gifterDuration||6)*1000))})}
window.triggerGifterLevelUp=triggerGifterLevelUp;
const gifterLevelCatalog=bind;bind=function(){gifterLevelCatalog();if(view!=='editor'&&view!=='overlay')return;let catalog=document.querySelector('.widget-catalog');if(!catalog||catalog.querySelector('[data-gifter-level]'))return;let section=document.createElement('section');section.dataset.gifterLevel='1';section.className='gifter-level-template-section';let glLayouts=[['profile','Modell 1 · Profil i orbit'],['number','Modell 2 · Stort nivånummer'],['stack','Modell 3 · Diamantstapel'],['sidebadge','Modell 4 · Sidobadge'],['reveal','Modell 5 · Diamantreveal'],['orbitlevel','Modell 6 · Orbitnivå'],['risingtier','Modell 7 · Stigande nivåer'],['flip','Modell 8 · Myntvändning'],['duo','Modell 9 · Kompakt duo']];section.innerHTML='<h4>GIFTER LEVEL UP · VARJE MODELL SEPARAT</h4>'+glLayouts.map(([l,label])=>`<button data-gifter-layout="${l}"><i>✦</i><span><b>${label}</b><small>Nivå · namn · profilbild</small></span></button>`).join('');catalog.prepend(section);section.querySelectorAll('button').forEach(b=>{const layout=b.dataset.gifterLayout,label=glLayouts.find(x=>x[0]===layout)[1],catalogKey='catalog:gifterlevel:'+layout;b.dataset.catalogKey=catalogKey;b.onclick=()=>{let created=VyraWidgets.create(catalogKey),id=created.id;state.widgets.push(created);selected=id;save();render();toast(label+' skapad')}})};

// Follower and Like Goals: three models, landscape and portrait.
// ---- livedrivna mal ------------------------------------------------------------------------------
// Renderarna laser runtimens varde nar det finns och faller tillbaka pa det sparade. Runtimen ar
// flyktig: den lever i en Map i sidan och skrivs aldrig till state.widgets eller localStorage.
function goalLiveFor(w){const runtime=window.VyraGoals;if(!runtime||!runtime.read||!w||!w.id)return null;const live=runtime.read(w.id);return live&&Number.isFinite(live.value)&&Number.isFinite(live.target)?live:null}

// En liveframe far kosta ett par attributskrivningar, inte en omrendering. render() bygger om hela
// #view och startar om varje Top Gift- och Top Streak-animation pa scenen; vid ingesttaket vore det
// hundra ombyggnader i sekunden. Darfor: bara de markta noderna, via textContent och style.
//
// Ingen innerHTML. Widget-id interpoleras aldrig i en selektor - noderna hamtas med ett fast
// attribututtryck och id:t jamfors exakt, sa ett legacy-id med citattecken eller hakparenteser
// varken kastar eller traffar granwidgeten. Sokningen ar scopad till .canvas, sa katalogens
// forhandsvisningar aldrig patchas.
function patchGoalDom(widgetId,goal){
  if(!goal||!widgetId)return 0;
  const target=Math.max(1,Number(goal.target)||1),value=Math.max(0,Number(goal.value)||0);
  const pct=Math.min(100,Math.round(value/target*100));
  let patched=0;
  const nodes=document.querySelectorAll('.canvas [data-goal]');
  for(const node of nodes){
    if(node.dataset.id === widgetId){
      const heart=node.dataset.goal==='heart';
      const text=(selector,value)=>{const el=node.querySelector(selector);if(el)el.textContent=value};
      text('[data-goal-value]',heart?String(value):value.toLocaleString('sv-SE'));
      text('[data-goal-target]',heart?String(target):target.toLocaleString('sv-SE'));
      text('[data-goal-pct]',pct+'% KLART');
      const fill=node.querySelector('[data-goal-fill]');
      if(fill)fill.style.width=pct+'%';
      node.style.setProperty('--goal-pct',pct);
      // premiumdesignen ritar sin stapel med .goal-track:before{width:var(--fill)}, sa bada
      // variablerna maste folja med - annars star den synliga stapeln stilla.
      node.style.setProperty('--fill',pct+'%');
      const clips=node.querySelectorAll('[data-goal-clip]');
      for(const clip of clips)clip.style.clipPath='inset('+(100-pct)+'% 0 0 0)';
      patched+=1;
    }
  }
  return patched;
}
window.VyraGoalDom={patch:patchGoalDom};
// En rAF-flush i runtimen -> ett patchpass har. Runtimen samlar frames; det har ar allt som ror DOM.
if(window.VyraGoals&&window.VyraGoals.subscribe)window.VyraGoals.subscribe(function(ids){for(const id of ids){const goal=window.VyraGoals.read(id);if(goal)patchGoalDom(id,goal)}});

