// OBS/TikTok-länken använder samma canvas och renderer som Studio, utan redigeringsgränssnittet.
// Widgets är positionerade i råa pixlar mot en design-yta på 432x768 — utan denna skalning skulle
// de sitta kvar i sin design-tidsstorlek oavsett vilken upplösning OBS/TikTok LIVE Studio faktiskt
// ger browser-source-fönstret, vilket är orsaken till att overlayen kunde se "större än tänkt" ut.
if(new URLSearchParams(location.search).has('overlay')){
  document.documentElement.classList.add('overlay-output');
  const fitOverlayCanvas=()=>{
    const canvas=document.querySelector('.canvas');
    if(!canvas)return;
    // ?widget= is handled by vyraRenderWidgets() before the markup is built — hiding widgets
    // here would mean every standalone instance was still constructed, animated and in the DOM.
    const scale=Math.min(window.innerWidth/432,window.innerHeight/768);
    canvas.style.left=((window.innerWidth-432*scale)/2)+'px';
    canvas.style.top=((window.innerHeight-768*scale)/2)+'px';
    canvas.style.transform=`scale(${scale})`;
  };
  const overlayFitRender=render;render=function(){overlayFitRender();fitOverlayCanvas()};
  window.addEventListener('resize',fitOverlayCanvas);
  setTimeout(()=>document.querySelector('[data-view="editor"]')?.click(),0);
}

