/* VYRA_PREMIUM_WIDGET_BUNDLE_20260812
   Activates the premium widget files that are already versioned in this repository.
   Keep the scripts sequential: premium-final and runtime-controls both extend bind(). */
Promise.resolve().then(()=>{
  // Premium-renderarna ersatter de klassiska renderarna. Den har maste bytas nar
  // premium-final.* andras; annars kan en cachead gammal renderer rita grunddesignen
  // samtidigt som panelen redan erbjuder de nya stilnamnen.
  const version='20260812-premium-widget-rendering';
  ['premium-final.css','runtime-controls.css'].forEach(href=>{
    if(document.querySelector('link[href^="'+href+'"]'))return;
    const css=document.createElement('link');
    css.rel='stylesheet';
    css.href=href+'?v='+version;
    css.dataset.vyraWidgetBundle='premium';
    document.head.append(css);
  });
  const scripts=['premium-final.js','runtime-controls.js','chatbot-controls.js'];
  const loadNext=index=>{
    if(index>=scripts.length)return;
    const src=scripts[index];
    if(document.querySelector('script[src^="'+src+'"]')){loadNext(index+1);return}
    const js=document.createElement('script');
    js.src=src+'?v='+version;
    js.async=false;
    js.dataset.vyraWidgetBundle='premium';
    js.onload=()=>loadNext(index+1);
    js.onerror=()=>console.error('[VYRA] failed to load premium widget module',src);
    (document.body||document.head).append(js);
  };
  loadNext(0);
});

/* GIFT JAR. Sju modeller, en burk som fylls av riktiga gavor.
   RUNTIME-TILLSTANDET LIGGER I EN Map, ALDRIG PA WIDGETOBJEKTET. Antalet gavor ar live-data;
   skrevs det till w.jarCount hade varje gava hamnat i den sparade layouten och blivit ett
   angra-steg. Det ar exakt tech-debt punkt 3, och den skulden ska inte aterskapas i en ny widget.
   Darfor: dropIntoGiftJar() rors DOM direkt och anropar aldrig save() eller render(). */
const GIFT_JAR_MODELS=VyraWidgets.variants('giftjar.model');
const giftJarRuntime=new Map();
function giftJarState(w){let live=giftJarRuntime.get(String(w.id));if(!live){live={count:Math.max(0,+w.jarCount||0),serial:0,timer:0,items:[]};giftJarRuntime.set(String(w.id),live)}return live}
/* Sokningen matchar EXAKT widget-id och ar begransad till de ytor dar widgets faktiskt ritas.
   Att bara saga '.canvas' racker inte: uppmatt 2026-08-10 renderas burken i overlay-vyn i
   .overlay-live-preview-stage, och .canvas finns inte pa den sidan alls — en .canvas-begransning
   hade gjort att live-gavor aldrig nadde burken dar anvandaren faktiskt tittar pa den.
   Id-matchningen ar det som barer sakerheten; behallarlistan ar batesele. Samma verkan som
   gift-fireworks.js, som soker pa [data-id="..."] utan behallare alls. */
const GIFT_JAR_YTOR='.canvas,.overlay-live-preview-stage,.overlay-stage,#view';
function giftJarRoot(w){return [...document.querySelectorAll(GIFT_JAR_YTOR)].flatMap(yta=>[...yta.querySelectorAll('.gift-jar-widget')]).find(node=>node.dataset.id===String(w.id))||null}
function giftJarKey(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toLowerCase()}
/* Gift Jar tar emot ALLA gavor. Punkt.
   Har fanns ett filter (vald gava / minsta coins) som foljde med fran referensgrenen utan
   att nagon fragade om det horde hemma. En burk som bara tar emot en gavosort ar ingen
   gavoburk.
   Redan sparade widgetar kan bara jarFilterMode, jarGiftName och jarMinCoins fran den
   tiden. De IGNORERAS — de raderas inte. Livevagen far aldrig skriva till den sparade
   layouten, och att stada bort falt vore precis den blinda skrivning §3 handlar om. */
function giftJarAccepts(){return true}
function giftJarImage(detail){let name=detail.giftName||detail.gift||detail.name,match=window.VyraGiftImages?.resolve?.(name),source=detail.giftImage||match?.file;return source?VyraSafe.src(source):''}
function updateGiftJarMeter(w,root,live){if(!root)return;let capacity=Math.max(1,+w.jarCapacity||50),progress=Math.min(100,live.count/capacity*100),counter=root.querySelector('.gift-jar-counter strong'),fill=root.querySelector('.gift-jar-fill');if(counter)counter.textContent=live.count+' / '+capacity;if(fill)fill.style.height=progress+'%';root.classList.toggle('jar-full',live.count>=capacity)}
function resetGiftJar(w){let live=giftJarState(w),root=giftJarRoot(w);clearTimeout(live.timer);live.timer=0;live.count=0;live.items.length=0;if(root)root.querySelectorAll('.gift-jar-item').forEach(item=>item.remove());updateGiftJarMeter(w,root,live)}
/* Ingen innerHTML har: varje partikel byggs som element och gavonamnet nar aldrig HTML-tolken.
   Namnet kommer fran TikTok via molnet och ar inte betrott innehall. */
function dropIntoGiftJar(w,detail={},forcedAmount){let root=giftJarRoot(w);if(!root||w.hidden||!giftJarAccepts(w,detail))return;let live=giftJarState(w),amount=Math.max(1,Math.floor(forcedAmount??(+detail.count||+detail.repeatCount||+detail.combo||1))),image=giftJarImage(detail),particles=Math.min(12,amount),well=root.querySelector('.gift-jar-items');live.count+=amount;for(let i=0;i<particles;i+=1){let item=document.createElement('span'),serial=live.serial++,settle=Math.max(8,72-Math.floor((serial%50)/6)*8);live.items.push({serial,image});item.className='gift-jar-item';item.style.setProperty('--jar-x',(12+(serial*37)%76)+'%');item.style.setProperty('--jar-y',settle+'%');item.style.setProperty('--jar-r',(-24+(serial*17)%49)+'deg');item.style.setProperty('--jar-delay',(i*.055)+'s');if(image){let img=document.createElement('img');img.alt='';img.src=image;item.append(img)}else item.textContent=w.jarSymbol||'\u25c6';well?.append(item)}if(live.items.length>50)live.items.splice(0,live.items.length-50);if(well)while(well.childElementCount>50)well.firstElementChild?.remove();updateGiftJarMeter(w,root,live);let capacity=Math.max(1,+w.jarCapacity||50),delay=Math.max(0,+w.jarAutoResetMs||0);if(live.count>=capacity&&delay>0){clearTimeout(live.timer);live.timer=setTimeout(()=>resetGiftJar(w),delay)}}
function triggerGiftJarDrop(detail={}){if(typeof state==='undefined'||!Array.isArray(state.widgets))return;state.widgets.filter(w=>w.type==='templateGiftJar').forEach(w=>dropIntoGiftJar(w,detail,detail.__amount))}
window.triggerGiftJarDrop=triggerGiftJarDrop;
window.addEventListener('vyra-live-event',event=>{let detail=event.detail||{},type=String(detail.type||detail.event||'').toLowerCase();if(type.includes('gift'))triggerGiftJarDrop(detail)});
/* Teardown vid kontobyte. Utan den bar runtime-Mappen forra kontots antal in i nasta session -
   samma lacka som tatades for angra/gor om. Widgetkontraktet kraver det. */
window.addEventListener('vyra-session-ended',()=>{giftJarRuntime.forEach(live=>clearTimeout(live.timer));giftJarRuntime.clear()});
function giftJarHtml(w){let model=GIFT_JAR_MODELS[w.jarModel]||GIFT_JAR_MODELS.crystal,live=giftJarState(w),capacity=Math.max(1,+w.jarCapacity||50),progress=Math.min(100,live.count/capacity*100),items=live.items.map(entry=>{let serial=entry.serial,settle=Math.max(8,72-Math.floor((serial%50)/6)*8),content=entry.image?'<img src="'+VyraSafe.url(entry.image)+'" alt="">':VyraSafe.text(w.jarSymbol||model.symbol);return '<span class="gift-jar-item" style="--jar-x:'+(12+(serial*37)%76)+'%;--jar-y:'+settle+'%;--jar-r:'+(-24+(serial*17)%49)+'deg;--jar-delay:0s">'+content+'</span>'}).join('');return '<div class="widget gift-jar-widget jar-'+VyraSafe.text(w.jarModel||'crystal')+(selected===w.id?' selected':'')+'" data-id="'+w.id+'" style="left:'+w.x+'px;top:'+w.y+'px;width:'+(w.width||250)+'px;--jar:'+VyraSafe.text(w.jarAccent||model.accent)+';--jar-light:'+VyraSafe.text(w.jarLight||model.light)+';zoom:'+(w.widgetScale||1)+'"><div class="gift-jar-aura"></div><div class="gift-jar-crown"><i></i><b>'+VyraSafe.text(w.jarSymbol||model.symbol)+'</b><i></i></div><div class="gift-jar-lid"><i></i><i></i><i></i></div><div class="gift-jar-glass"><div class="gift-jar-fill" style="height:'+progress+'%"></div><div class="gift-jar-items">'+items+'</div><div class="gift-jar-shine"></div><div class="gift-jar-facets"><i></i><i></i><i></i></div></div><div class="gift-jar-base"><i></i><strong>'+VyraSafe.text(model.label)+'</strong><i></i></div><div class="gift-jar-counter" style="display:'+(w.jarShowCounter===false?'none':'flex')+'"><span>GIFTS</span><strong>'+live.count+' / '+capacity+'</strong></div>'+(selected===w.id?'<span class="resize-handle">\u2198</span>':'')+'</div>'}
const giftJarWh=wh;wh=function(w){return w.type==='templateGiftJar'?giftJarHtml(w):giftJarWh(w)};
const giftJarProps=props;props=function(){let w=liveWidget(selected);if(!w||w.type!=='templateGiftJar')return giftJarProps();return '<h3>GIFT JAR</h3><div class="template-badge">7 MODELLER \u00b7 LIVE GIFTS</div><div hidden><input id="pt" value="'+VyraSafe.text(w.title||'Gift Jar')+'"><input id="pv" value=""></div><div class="property-group"><h4>ALLM\u00c4NT</h4><label>Modell<select id="jarModel">'+Object.entries(GIFT_JAR_MODELS).map(([id,m])=>'<option value="'+id+'" '+(w.jarModel===id?'selected':'')+'>'+VyraSafe.text(m.label)+'</option>').join('')+'</select></label><div class="switch-row one"><label><input id="jarShowCounter" type="checkbox" '+(w.jarShowCounter===false?'':'checked')+'> Visa r\u00e4knare</label></div><div class="property-grid"><label>Full vid<input id="jarCapacity" type="number" min="1" max="9999" value="'+(w.jarCapacity||50)+'"></label><label>Auto-reset, ms<input id="jarAutoReset" type="number" min="0" max="60000" step="500" value="'+(w.jarAutoResetMs||0)+'"></label></div></div><div class="property-group"><h4>F\u00c4RGER</h4><div class="color-grid"><label>Huvudf\u00e4rg<input id="jarAccent" type="color" value="'+VyraSafe.text(w.jarAccent||'#b98cff')+'"></label><label>Ljus<input id="jarLight" type="color" value="'+VyraSafe.text(w.jarLight||'#76e7ff')+'"></label></div></div><div class="property-group"><h4>TEST OCH RESET</h4><div class="property-actions"><button id="jarDropTest" type="button">Sl\u00e4pp 5 testg\u00e5vor</button><button id="jarReset" type="button">T\u00f6m burken</button></div><button id="jarDefaults" type="button">\u00c5terst\u00e4ll till standard</button></div><div class="property-group"><h4>POSITION OCH STORLEK</h4><div class="property-grid"><label>X<input id="propX" type="number" value="'+(w.x||0)+'"></label><label>Y<input id="propY" type="number" value="'+(w.y||0)+'"></label><label>Bredd<input id="propWidth" type="number" min="100" max="700" value="'+(w.width||250)+'"></label><label>Lager<input id="propLayer" type="number" min="0" max="99" value="'+(w.layer||1)+'"></label></div></div><button class="delete" id="del">Ta bort</button>'};
const giftJarBind=bind;bind=function(){giftJarBind();if(view!=='editor')return;let w=liveWidget(selected);if(!w||w.type!=='templateGiftJar')return;let set=(id,key,num=false)=>{let el=document.querySelector(id);if(el)el.onchange=e=>{w[key]=num?+e.target.value:e.target.value;save();render()}};set('#jarCapacity','jarCapacity',true);set('#jarAutoReset','jarAutoResetMs',true);set('#jarAccent','jarAccent');set('#jarLight','jarLight');document.querySelector('#jarShowCounter')?.addEventListener('change',e=>{w.jarShowCounter=e.target.checked;save();render()});document.querySelector('#jarModel')?.addEventListener('change',e=>{let m=GIFT_JAR_MODELS[e.target.value];w.jarModel=e.target.value;w.jarAccent=m.accent;w.jarLight=m.light;w.jarSymbol=m.symbol;save();render()});document.querySelector('#jarDropTest')?.addEventListener('click',()=>triggerGiftJarDrop({type:'gift',giftName:'Rose',giftImage:'assets/gifts/events/0001_Rose.png',__amount:5}));document.querySelector('#jarReset')?.addEventListener('click',()=>resetGiftJar(w));document.querySelector('#jarDefaults')?.addEventListener('click',()=>{let m=GIFT_JAR_MODELS.crystal;Object.assign(w,{jarModel:'crystal',jarAccent:m.accent,jarLight:m.light,jarSymbol:m.symbol,jarCapacity:50,jarShowCounter:true,jarAutoResetMs:0});resetGiftJar(w);save();render()})};
const giftJarCatalogBind=bind;bind=function(){giftJarCatalogBind();if(view!=='editor'&&view!=='overlay')return;let catalog=document.querySelector('.widget-catalog');if(!catalog||catalog.querySelector('[data-gift-jar]'))return;let section=document.createElement('section');section.dataset.giftJar='1';section.className='gift-jar-template-section';let rubrik=document.createElement('h4');rubrik.textContent='GIFT JAR \u00b7 VARJE MODELL SEPARAT';section.append(rubrik);Object.entries(GIFT_JAR_MODELS).forEach(([model,m])=>{let button=document.createElement('button');button.style.setProperty('--swatch',m.accent);let ikon=document.createElement('i');ikon.textContent=m.symbol;let text=document.createElement('span'),namn=document.createElement('b'),under=document.createElement('small');namn.textContent=m.label;under.textContent='Live gifts \u00b7 transparent';text.append(namn,under);button.append(ikon,text);button.dataset.jarModel=model;button.dataset.catalogKey='catalog:giftjar:'+model;/* Nyckeln skrivs EN gang och lases tillbaka ur knappen. Att upprepa strangen i create() gor att den publicerade nyckeln och den anvanda kan sara sig — ett prov vaktar just det. */button.onclick=()=>{let created=VyraWidgets.create(button.dataset.catalogKey);state.widgets.push(created);selected=created.id;save();render();toast(m.label+' skapad')};section.append(button)});catalog.prepend(section)};
